{"content":"#!/usr/bin/env python3
"""
HTTP JSON API server using only Python standard library.
Usage: python3 server.py <port>
"""

import sys
import json
import socket
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse


class JSONRequestHandler(BaseHTTPRequestHandler):
    def _send_json(self, status_code, data):
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(data).encode("utf-8"))

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == "/health":
            self._send_json(200, {"status": "ok"})
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path != "/sum":
            self._send_json(404, {"error": "not found"})
            return

        content_length = self.headers.get("Content-Length")
        if not content_length:
            self._send_json(400, {"error": "missing content-length"})
            return

        try:
            body = self.rfile.read(int(content_length)).decode("utf-8")
            data = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            self._send_json(400, {"error": "invalid json"})
            return

        numbers = data.get("numbers")
        if not isinstance(numbers, list):
            self._send_json(400, {"error": "numbers must be a list"})
            return

        try:
            total = sum(numbers)
        except TypeError:
            self._send_json(400, {"error": "all elements must be numbers"})
            return

        self._send_json(200, {"sum": total})

    def log_message(self, format, *args):
        # Suppress default log messages
        pass


def main():
    if len(sys.argv) != 2:
        print("Usage: python3 server.py <port>", file=sys.stderr)
        sys.exit(1)

    try:
        port = int(sys.argv[1])
    except ValueError:
        print("Port must be an integer", file=sys.stderr)
        sys.exit(1)

    server = HTTPServer(("127.0.0.1", port), JSONRequestHandler)
    print(f"Server listening on 127.0.0.1:{port}", file=sys.stderr)
    server.serve_forever()


